index 0000000..b7d8249
--- /dev/null
+++ b/scripts/check-stripe-migration.js
@@ -0,0 +1,10 @@
+const fs = require('fs');
+const path = require('path');
+const assert = require('assert');
+const root = path.join(__dirname, '..');
+const src = fs.readFileSync(path.join(root, 'server.js'), 'utf8');
+assert(!/payment_method_types/.test(src), 'payment_method_types must be removed');
+assert(!/constructEventWithoutVerification|ErrorType/.test(src));
+const v = JSON.parse(fs.readFileSync(path.join(root, 'node_modules/stripe/package.json'), 'utf8')).version;
+assert(v.startsWith('23.'), 'stripe installed version should be 23.x, got ' + v);
+console.log('ok');
